contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 mintedAmount) public {
        c.mintToken(address(this), mintedAmount); if (__ESBMC_reverted()) return;
        assert(c.balanceOf(address(this)) == c.totalSupply() && c.balanceOf(address(this)) >= mintedAmount);
    }
    receive() external payable {}
}

