// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 mintedAmount) internal {
        try c.mintToken(address(this), mintedAmount) {} catch { return; }
        assertTrue(c.balanceOf(address(this)) == c.totalSupply() && c.balanceOf(address(this)) >= mintedAmount);
    }

    function testFuzz_run(uint256 mintedAmount) public {
        _run(mintedAmount);
    }

    receive() external payable {}
}
